function mwMd5Hex(s) {
  var md = Packages.java.security.MessageDigest.getInstance("MD5");
  var dig = md.digest(new Packages.java.lang.String(s).getBytes("UTF-8"));
  var hex = "";
  for (var i = 0; i < dig.length; i++) {
    var b = dig[i] & 0xff;
    hex += ("0" + b.toString(16)).slice(-2);
  }
  return hex;
}

function mwB64Decode(s) {
  s = String(s).replace(/[^A-Za-z0-9+/=]/g, "");
  try {
    return Packages.java.util.Base64.getDecoder().decode(s);
  } catch (e) {
    return Packages.android.util.Base64.decode(s, 0);
  }
}

function mwDecrypt(b64, suffix) {
  var keyStr = mwMd5Hex(String(suffix) + MW_KEY_SALT);
  var keyBytes = new Packages.java.lang.String(keyStr).getBytes("UTF-8");
  var cipher = Packages.javax.crypto.Cipher.getInstance("AES/ECB/PKCS5Padding");
  cipher.init(Packages.javax.crypto.Cipher.DECRYPT_MODE,
    new Packages.javax.crypto.spec.SecretKeySpec(keyBytes, "AES"));
  var pt = cipher.doFinal(mwB64Decode(b64));
  return String(new Packages.java.lang.String(pt, "UTF-8"));
}

// One raw GET with the app's Devid/X-Token headers. Returns {code, body, devid}.
function mwHttpGet(url, cto, rto) {
  var devid = String(new Date().getTime());
  var token = mwMd5Hex(devid + MW_TOKEN_SALT);
  var conn = new Packages.java.net.URL(url).openConnection();
  conn.setRequestMethod("GET");
  conn.setConnectTimeout(cto || 15000);
  conn.setReadTimeout(rto || 20000);
  conn.setInstanceFollowRedirects(true);
  conn.setRequestProperty("Devid", devid);
  conn.setRequestProperty("X-Token", token);
  conn.setRequestProperty("User-Agent", MW_UA);
  conn.setRequestProperty("Accept", "application/json");
  conn.setRequestProperty("Accept-Encoding", "identity");
  var code = conn.getResponseCode();
  var stream = code >= 400 ? conn.getErrorStream() : conn.getInputStream();
  var body = "";
  if (stream != null) {
    if ("gzip" == String(conn.getContentEncoding())) {
      stream = new Packages.java.util.zip.GZIPInputStream(stream);
    }
    var reader = new Packages.java.io.BufferedReader(
      new Packages.java.io.InputStreamReader(stream, "UTF-8"));
    var sb = new Packages.java.lang.StringBuilder();
    var line;
    while ((line = reader.readLine()) != null) { sb.append(line); }
    reader.close();
    body = String(sb.toString());
  }
  var respDevid = conn.getHeaderField("Devid");
  conn.disconnect();
  return { code: code, body: body, devid: respDevid ? String(respDevid) : devid };
}

// Decode one response body to the API JSON string, or null when it is not
// a genuine API response (e.g. the gateway's 302 disguise page).
function mwDecode(r) {
  if (r.code != 200 || !r.body) { return null; }
  var body = String(r.body).replace(/^\s+|\s+$/g, "");
  if (body.charAt(0) == "{") { return body; }
  try {
    var plain = mwDecrypt(body, r.devid);
    if (plain && plain.charAt(0) == "{") { return plain; }
  } catch (e1) {}
  // ISP-injection fallback (same strategy as the app): longest base64 block.
  var blocks = body.match(/[A-Za-z0-9+/]+={0,2}/g) || [];
  blocks.sort(function (a, b) { return b.length - a.length; });
  for (var j = 0; j < blocks.length && j < 5; j++) {
    if (blocks[j].length < 40) { break; }
    try {
      var p2 = mwDecrypt(blocks[j], r.devid);
      if (p2 && p2.charAt(0) == "{") { return p2; }
    } catch (e2) {}
  }
  return null;
}

// Best-line cache, persisted in the source's own variable store so it
// survives across searches; falls back to a plain global when unavailable.
var MW_BEST_TTL = 30 * 60 * 1000;
var _mwBestMem = null;
// Persistent per-source variable store (java.put/get is Legado's own
// variable API and is shared with the login page; source.put/get and a
// plain global are fallbacks).
var _mwMem = {};
function mwStoreGet(k) {
  try {
    if (typeof java != "undefined" && java && java.get) { var v = java.get(k); if (v) { return v; } }
  } catch (e) {}
  try {
    if (typeof source != "undefined" && source && source.get) { var v2 = source.get(k); if (v2) { return v2; } }
  } catch (e) {}
  return _mwMem[k] || null;
}
function mwStorePut(k, v) {
  _mwMem[k] = v;
  try { if (typeof java != "undefined" && java && java.put) { java.put(k, v); } } catch (e) {}
  try { if (typeof source != "undefined" && source && source.put) { source.put(k, v); } } catch (e) {}
}

// Manual line chosen on the login page: "1".."5" pins MW_LINES[n-1],
// anything else means automatic selection.
function mwManualLine() {
  var v = mwStoreGet("mw_line");
  if (v && /^[1-5]$/.test(String(v))) { return MW_LINES[parseInt(v, 10) - 1]; }
  return null;
}

// Map one app book item to the standardized object the rules return
// (same field names as the web source: name/author/cover/intro/kind/
// latest/word/url).
function mwBookObj(b) {
  var kind = "";
  if (b.serialize) { kind = String(b.serialize); }
  if (b.category_name) { kind = kind ? kind + "$$" + b.category_name : String(b.category_name); }
  return {
    name: b.name || "",
    author: b.author || "",
    cover: b.picx || b.pic || "",
    intro: b.text || b.description || "",
    kind: kind,
    latest: b.last_chapter || "",
    word: (b.hits != null ? String(b.hits) : ""),
    url: mwCurBase() + "/api/detail/index?id=" + b.id
  };
}

function mwBestGet() {
  try {
    var v = mwStoreGet("mw_best_line");
    if (!v && _mwBestMem) { v = _mwBestMem; }
    if (!v) { return null; }
    var parts = String(v).split("|");
    var line = parts[0];
    var ts = parseInt(parts[1] || "0", 10);
    if (!line || new Date().getTime() - ts > MW_BEST_TTL) { return null; }
    return line;
  } catch (e) { return null; }
}
function mwBestSet(line) {
  var v = line + "|" + new Date().getTime();
  _mwBestMem = v;
  mwStorePut("mw_best_line", v);
}

// Try one line for this path with probe timeouts; return decoded JSON or null.
function mwTryLine(line, path) {
  try {
    var r = mwHttpGet(line + path, 6000, 12000);
    return mwDecode(r);
  } catch (e) { return null; }
}

// Probe every line with this very request; the fastest successful line
// wins, gets cached as the best line, and its response is returned.
function mwProbe(path) {
  var bestLine = null;
  var bestMs = -1;
  var bestPlain = null;
  for (var i = 0; i < MW_LINES.length; i++) {
    var t0 = new Date().getTime();
    var plain = mwTryLine(MW_LINES[i], path);
    var ms = new Date().getTime() - t0;
    if (plain && (bestMs < 0 || ms < bestMs)) {
      bestLine = MW_LINES[i];
      bestMs = ms;
      bestPlain = plain;
    }
  }
  if (bestLine) { mwBestSet(bestLine); }
  return bestLine ? { line: bestLine, plain: bestPlain } : null;
}

// Decoded responses captured while resolving a URL (search), so the
// matching mwApi call does not fetch twice.
var _mwStash = {};
// Line that actually served the most recent successful request in this
// run; generated content links (detail/toc/chapter) use it so the URLs
// the app shows rotate to whichever domain is alive, instead of being
// pinned to one hardcoded host.
var _mwLastBase = null;
function mwCurBase() {
  if (_mwLastBase) { return _mwLastBase; }
  var b = mwBestGet();
  return b || MW_LINES[0];
}
function mwResolve(path) {
  var best = mwBestGet();
  if (best) { return { base: best }; }
  var r = mwProbe(path);
  if (r) {
    _mwStash[path] = r.plain;
    return { base: r.line };
  }
  return { base: MW_LINES[0] };
}

// The currently selected line (auto-picked by network speed), for
// building visible URLs; falls back to the first line before any probe.
function mwBase() {
  var b = mwBestGet();
  if (b) { return b; }
  var r = mwProbe('/api/search/index?k=a&page=1');
  return r ? r.line : MW_LINES[0];
}

// Call an API path on the line that works fastest on the current network.
// The cached best line is tried first; on failure (or no cache) every line
// is probed with this very request and the fastest successful one wins and
// is cached, so later calls go straight to it.
function mwApi(path) {
  if (_mwStash[path]) {
    var v = _mwStash[path];
    delete _mwStash[path];
    return v;
  }
  var manual = mwManualLine();
  if (manual) {
    var mhit = mwTryLine(manual, path);
    if (mhit) { _mwLastBase = manual; return mhit; }
  }
  var best = mwBestGet();
  if (best) {
    var hit = mwTryLine(best, path);
    if (hit) { _mwLastBase = best; return hit; }
  }
  var r = mwProbe(path);
  if (r) { _mwLastBase = r.line; return r.plain; }
  return "{\"code\":-1,\"data\":{},\"msg\":\"all lines failed\"}";
}

function mwImgHost(d) {
  var domains = d.img_domains || d.imgHosts || [];
  var h = d.img_host;
  if (h == null) { return domains.length ? String(domains[0]) : ""; }
  if (typeof h === "number") { return domains.length ? String(domains[Math.min(h, domains.length - 1)]) : ""; }
  h = String(h);
  if (h.indexOf("http") == 0) { return h; }
  if (/^\d+$/.test(h) && domains.length) { return String(domains[Math.min(parseInt(h, 10), domains.length - 1)]); }
  return h;
}

function mwJoinUrl(host, p) {
  p = String(p);
  if (p.indexOf("http") == 0) { return p; }
  if (p.indexOf("//") == 0) { return "https:" + p; }
  if (!host) { return p; }
  var hh = String(host).replace(/\/+$/, "");
  if (hh.indexOf("http") != 0) { hh = "https://" + hh; }
  return hh + (p.charAt(0) == "/" ? p : "/" + p);
}

// ===== domain entry point, same pattern as the reference source =====
// URL fields call {{Url()}}; it returns the line that is alive right
// now (manual choice first, then the cached fastest line, then a fresh
// probe), so every search/explore URL rotates automatically when a
