function mwLine(n) {
  java.put("mw_line", String(n));
  if (n == 0) {
    java.toast("漫蛙：已切换为自动选线");
  } else {
    java.toast("漫蛙：已切换到线路 " + n);
  }
}
function mwShowLine() {
  var m = java.get("mw_line");
  var best = java.get("mw_best_line");
  var msg = "当前设置：" + (!m || m == "0" ? "自动选线" : "手动线路 " + m);
  if (best) { msg += "\n自动选线缓存：" + String(best).split("|")[0]; }
  java.toast(msg);
}
function mwReset() {
  java.put("mw_line", "0");
  java.put("mw_best_line", "");
  java.toast("漫蛙：已恢复默认（自动选线）");
}
